parameters.jsCode:
for (const item of $input.all()) {
  let rawText = item.json.output;

  if (rawText) {
    try {
      // Remove Markdown code block wrappers (both ```json and ```)
      let cleanJsonString = rawText
        .replace(/^```json\s*/i, "")
        .replace(/^```\s*/i, "")
        .replace(/\s*```$/g, "")
        .trim();

      // Parse the JSON
      let parsedData = JSON.parse(cleanJsonString);

      // Clean up image_prompt
      if (parsedData.image_prompt) {
        parsedData.image_prompt = parsedData.image_prompt
          .replace(/\r\n/g, "\n")
          .replace(/\s+/g, " ")
          .trim();
      }

      // Clean up veo_prompts array - ALL 4 SCENES
      if (Array.isArray(parsedData.veo_prompts)) {
        parsedData.veo_prompts = parsedData.veo_prompts
          .map(prompt => {
            return prompt
              .replace(/\r\n/g, "\n")
              .replace(/\s+/g, " ")
              .trim();
          });
      }

      // Normalize all text fields
      const textFields = ["ad_script", "post_title", "description", "keywords", "hashtags"];
      textFields.forEach(field => {
        if (parsedData[field]) {
          parsedData[field] = parsedData[field]
            .replace(/\r\n/g, "\n")
            .replace(/\s+/g, " ")
            .trim();
        }
      });

      // Replace the item with parsed data
      item.json = parsedData;

    } catch (error) {
      // If JSON parsing fails, log the error and keep original data
      console.error("JSON parse error:", error.message);
      console.error("Raw text:", rawText.substring(0, 200)); // Log first 200 chars for debugging

      // Optionally, you can set an error flag
      item.json.parseError = true;
      item.json.errorMessage = error.message;
    }
  }

}
return $input.all();
